data <- data.frame(
  x = c(0, 1, 0.5, 2),
  y = c(0, 0, 1, 0.5)
)

one <- function() {
  cs <- corLin(2.5, form = ~ x + y, metric = "eu")
  cs <- Initialize(cs, data)
  as.vector(corMatrix(cs))
}

value <- one()
